fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    let len = dst.len(); // All vectors are guaranteed to be the same length
    let mut result = Vec::with_capacity(len); // Preallocate memory for the result vector

    for i in 0..len {
        if mask[i] {
            result.push(src[i]); // Take from src if mask is true
        } else {
            result.push(dst[i]); // Take from dst if mask is false
        }
    }

    result // Return the constructed result vector
}